from pathlib import Path
import json,csv,subprocess,html,re,collections
root=Path('/mnt/data/voice_audit')
m=json.loads((root/'audio/cedar-map.json').read_text())
steps=json.loads((root/'audit_data.json').read_text()); look={s['key']:s for s in steps}
lines=[('greeting','שלום וברוכים הבאים'),('foundations','ראשית נתחיל מהיסודות'),('principle','יסוד גדול בעבודת השם'),('reflection','אז מה אנחנו לומדים מכאן'),('morning','בוקר טוב לכולם'),('attention','שימו לב אנחנו מתחילים עכשיו'),('progress','יפה מאוד התקדמנו'),('review','עכשיו נחזור על הנקודה'),('reassure','אל תדאגו נעבור על זה'),('together','בעזרת השם נצליח')]
rows=[]
for key,entry in m.items():
 path=root/'audio'/entry['file']; src=entry['script']; original=look.get(key,{}).get('original','')
 proc=subprocess.run(['ffprobe','-v','error','-show_entries','format=duration','-of','default=nokey=1:noprint_wrappers=1',str(path)],capture_output=True,text=True)
 dur=round(float(proc.stdout or 0),2)
 issues=[]
 if key in ('intro-1','intro-3'): issues.append('שגיאת הגייה ידועה – להקליט מחדש')
 if key in ('intro-2','intro-3'): issues.append('גבול חיתוך שתוקן בקירוב – לאמת בהאזנה')
 if len(src)/max(dur,.1)>12: issues.append('קצב צפוף ביחס לאורך הטקסט – לבדוק')
 if key.startswith(('flow-','transfer-')): issues.append('שיעור חדש – חיתוך ראשוני לא אומת')
 rows.append(dict(key=key,category='שיעור',lesson=look.get(key,{}).get('lesson','תרגול יומי'),audio='audio/'+entry['file'],seconds=dur,transcript=src,source_text_matches=('כן' if (re.sub(r'[^\u0590-\u05ff]','',src).replace('רבידוד','ר דוד')==re.sub(r'[^\u0590-\u05ff]','',original)) else 'בדיקה'),flags='; '.join(issues)))
for key,title in lines:
 path=root/'audio/recordings'/f'{key}.mp3'; dur=float(subprocess.run(['ffprobe','-v','error','-show_entries','format=duration','-of','default=nokey=1:noprint_wrappers=1',str(path)],capture_output=True,text=True).stdout)
 rows.append(dict(key='event-'+key,category='משפט ליווי',lesson='משפטי ליווי',audio=f'audio/recordings/{key}.mp3',seconds=round(dur,2),transcript=title,source_text_matches='לא נבדק',flags='תמלול קצר לזיהוי בלבד – לוודא בהאזנה'))
with open(root/'דוח_בקרת_הקלטות.csv','w',encoding='utf-8-sig',newline='') as f:
 w=csv.DictWriter(f,fieldnames=list(rows[0].keys()));w.writeheader();w.writerows(rows)
(root/'qa-data.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding='utf-8')
page='''<!doctype html><html lang="he" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>בדיקת הקלטות — קול בטוח</title><style>
:root{font-family:system-ui,Arial,sans-serif;color:#193b3d;background:#f5f7f7}*{box-sizing:border-box}body{margin:0}.wrap{max-width:1100px;margin:auto;padding:20px}h1{margin-bottom:4px}.muted{color:#61777b}.panel{background:white;border:1px solid #d7e2e3;border-radius:16px;padding:16px;margin:16px 0;box-shadow:0 3px 14px #1233}button,select,input{font:inherit}button,a.action{border-radius:10px;border:1px solid #8fa9aa;padding:9px 13px;background:white;color:#114b4f;cursor:pointer;text-decoration:none}button.primary{background:#155e63;color:white}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #ffba70}input[type=search],select{padding:10px;border-radius:9px;border:1px solid #aac0bf;background:white;max-width:100%}.tools{display:flex;gap:8px;flex-wrap:wrap;align-items:center}article{border-top:1px solid #dce6e5;padding:16px 0;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px}.caption{font-size:1rem;line-height:1.8;white-space:pre-wrap}audio{max-width:100%;width:410px}small{display:block}.warn{font-size:.88rem;color:#865d14}.ok{color:#13734e}.tag{display:inline-block;background:#e5f2f0;border-radius:8px;padding:3px 7px;font-size:.82rem}.state{display:flex;gap:7px;flex-wrap:wrap;align-items:center}@media(max-width:730px){article{grid-template-columns:1fr}audio{width:100%}} </style></head><body><main class="wrap"><h1>בדיקת ההקלטות של ר׳ דוד</h1><p class="muted">מסך לבקרת איכות. קובצי השמע נשמרים באתר; סימוני הבדיקה נשמרים בדפדפן שלך בלבד. המסך אינו שולח מידע לשרת.</p><div class="panel"><div class="tools"><input id="search" type="search" placeholder="חיפוש בשיעור או בטקסט" aria-label="חיפוש"><select id="filter" aria-label="סינון מצב"><option value="all">הכול</option><option value="todo">טרם נבדקו</option><option value="bad">דורשים תיקון</option><option value="good">תקינים</option></select><button id="export" class="primary">ייצוא תוצאות ל־CSV</button><a class="action" href="./index.html">חזרה לאתר</a></div><p id="counts" class="muted"></p></div><section class="panel" id="items" aria-label="הקלטות"></section></main><script type="module">
const rows=await fetch('qa-data.json').then(r=>r.json()); const $=id=>document.getElementById(id);let playing=null;
function statuses(){try{return JSON.parse(localStorage.getItem('kol-batuach-qa-v1')||'{}')}catch{return {}}}let state=statuses();
function save(k,val){state[k]=val;localStorage.setItem('kol-batuach-qa-v1',JSON.stringify(state));draw()}
function draw(){const q=$('search').value.trim(), f=$('filter').value; const showing=rows.filter(r=>(!q||`${r.key} ${r.lesson} ${r.transcript}`.includes(q))&&(f==='all'||(f==='todo'?!state[r.key]:state[r.key]===f)));let ok=rows.filter(x=>state[x.key]==='good').length,bad=rows.filter(x=>state[x.key]==='bad').length;$('counts').textContent=`${rows.length} קטעים · ${ok} תקינים · ${bad} דורשים תיקון · ${rows.length-ok-bad} טרם נבדקו · ${showing.length} מוצגים`;const frag=document.createDocumentFragment();showing.forEach(r=>{const a=document.createElement('article');const body=document.createElement('div'); const h=document.createElement('h3');h.textContent=`${r.lesson} — ${r.key}`;const cap=document.createElement('div');cap.className='caption';cap.textContent=r.transcript;const meta=document.createElement('small');meta.className='muted';meta.textContent=`${r.seconds.toFixed(1)} שניות · ${r.category}`;body.append(h,cap,meta);if(r.flags){const warn=document.createElement('p');warn.className='warn';warn.textContent='לבדיקה: '+r.flags;body.append(warn)}const controls=document.createElement('div');const aud=document.createElement('audio');aud.controls=true;aud.preload='none';aud.src=r.audio;aud.addEventListener('play',()=>{if(playing&&playing!==aud)playing.pause();playing=aud});const st=document.createElement('div');st.className='state';[['good','✓ תקין'],['bad','⚠ דורש תיקון'],['todo','נקה סימון']].forEach(([v,label])=>{const b=document.createElement('button');b.textContent=label;b.setAttribute('aria-pressed',String(state[r.key]===v));if(state[r.key]===v)b.className='primary';b.onclick=()=>save(r.key,v==='todo'?null:v);st.append(b)});controls.append(aud,st);a.append(body,controls);frag.append(a)});$('items').replaceChildren(frag)}
$('search').addEventListener('input',draw);$('filter').addEventListener('change',draw);$('export').onclick=()=>{const val=x=>'"'+String(x??'').replaceAll('"','""')+'"';const csv='\\uFEFF'+[['מזהה','שיעור','משך','מצב','תמלול','הערות'],...rows.map(r=>[r.key,r.lesson,r.seconds,state[r.key]==='good'?'תקין':state[r.key]==='bad'?'דורש תיקון':'לא נבדק',r.transcript,r.flags])].map(row=>row.map(val).join(',')).join('\\r\\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download='תוצאות_בדיקת_הקלטות.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};draw();
</script></body></html>'''
# make export BOM real unicode in JS literal (not escaped sequence)
page=page.replace("'\\uFEFF'", "'\\uFEFF'")
(root/'qa.html').write_text(page,encoding='utf-8')
print('Made',len(rows),'audio entries')
